import { Component, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { RouterModule, Router } from '@angular/router';
import { AuthService } from '../services/auth.service';

@Component({
  selector: 'app-dashboard',
  standalone: true,
  imports: [CommonModule, RouterModule],
  templateUrl: './dashboard.component.html',
  styleUrls: ['./dashboard.component.css'],
})
export class DashboardComponent implements OnInit {
  usuario: any;

  modules = [
    { name: 'Clientes', icon: '👥', path: '/clientes', description: 'Gestión de clientes' },
    {
      name: 'Contactos',
      icon: '📞',
      path: '/contactos',
      description: 'Contactos de clientes',
    },
    {
      name: 'Oportunidades',
      icon: '💼',
      path: '/oportunidades',
      description: 'Oportunidades de venta',
    },
    { name: 'Actividades', icon: '📋', path: '/actividades', description: 'Actividades' },
    { name: 'Reportes', icon: '📊', path: '/reportes', description: 'Reportes y análisis' },
  ];

  constructor(
    private authService: AuthService,
    private router: Router,
  ) {}

  ngOnInit() {
    this.usuario = this.authService.getUsuario();
  }

  logout() {
    this.authService.logout();
    this.router.navigate(['/login']);
  }
}
<div class="dashboard">
  <header class="navbar">
    <div class="navbar-container">
      <h1 class="navbar-title">Innovacion CRM</h1>
      <div class="navbar-user">
        <span class="user-name" *ngIf="usuario">{{ usuario.nombres }} {{ usuario.apellidos }}</span>
        <button class="btn btn-logout" (click)="logout()">Logout</button>
      </div>
    </div>
  </header>

  <main class="main-content">
    <div class="welcome-section">
      <h2>Bienvenido, {{ usuario?.nombres }}</h2>
      <p>Selecciona un módulo para comenzar</p>
    </div>

    <div class="modules-grid">
      <a *ngFor="let module of modules" [routerLink]="module.path" class="module-card">
        <div class="module-icon">{{ module.icon }}</div>
        <h3>{{ module.name }}</h3>
        <p>{{ module.description }}</p>
      </a>
    </div>
  </main>
</div>
